command:
// DSCT: Concealing Area
//
// Drops a region that conceals anything standing in it: fog, smoke, a darkness spell, thick
// undergrowth. Anything entering gains Concealment and loses it again on the way out.
//
// Pick the shape and size, then place it on the map. Afterwards it is an ordinary region, so the
// region tools can reshape it and its behaviour can be edited on its sheet.
const M = 'draw-steel-combat-tools';
if (!game.modules.get(M)?.active) { ui.notifications.error('Draw Steel: Combat Tools is not active.'); return; }
if (!canvas.scene) { ui.notifications.warn('Open a scene first.'); return; }

const { DialogV2 } = foundry.applications.api;

const CONTENT = `
  <div class="form-group">
    <label>Shape</label>
    <div class="form-fields">
      <select name="shape">
        <option value="burst">Burst, a circle</option>
        <option value="cube">Cube, a square</option>
        <option value="line">Line, a long rectangle</option>
      </select>
    </div>
  </div>
  <div class="form-group">
    <label>Size</label>
    <div class="form-fields"><input type="number" name="size" value="3" min="1" step="1"></div>
    <p class="hint">The radius of a burst, the side of a cube, or the length of a line, in squares.</p>
  </div>
  <div class="form-group">
    <label>Width</label>
    <div class="form-fields"><input type="number" name="width" value="1" min="1" step="1"></div>
    <p class="hint">Used by a line only.</p>
  </div>
  <div class="form-group">
    <label>Colour</label>
    <div class="form-fields"><input type="text" name="color" value="#9aa0a6"></div>
    <p class="hint">How the area is tinted on the map. Leave it alone to follow the magical tickbox.</p>
  </div>
  <div class="form-group">
    <label>Magical</label>
    <div class="form-fields"><input type="checkbox" name="magical"></div>
    <p class="hint">Magical concealment, for a darkness spell rather than a smoke cloud. The system
      treats the two differently.</p>
  </div>`;

// Read while the dialog is still open. Querying after it resolves finds nothing, because the
// application has already torn its own DOM down by then.
const field = (dialog, name) => dialog.element.querySelector(`[name="${name}"]`);
const gather = (_event, _button, dialog) => ({
  shape: field(dialog, 'shape')?.value ?? 'burst',
  size: Math.max(1, Number(field(dialog, 'size')?.value) || 3),
  lineWidth: Math.max(1, Number(field(dialog, 'width')?.value) || 1),
  magical: !!field(dialog, 'magical')?.checked,
  color: field(dialog, 'color')?.value?.trim() || null,
  touched: field(dialog, 'color')?.dataset.dsctTouched === '1',
});

const dressUp = (_event, _element, dialog) => {
  const el = dialog?.element ?? _element;
  try { game.modules.get(M)?.api?.colorFields?.(el); } catch { /* a plain text box will do */ }
  const box = el?.querySelector?.('[name="color"]');
  box?.addEventListener('change', () => { box.dataset.dsctTouched = '1'; });
};

const answer = await DialogV2.wait({
  window: { title: 'Concealing Area' },
  position: { width: 400 },
  content: CONTENT,
  buttons: [
    { action: 'place', label: 'Place It', icon: 'fa-solid fa-cloud', default: true, callback: gather },
    { action: 'cancel', label: 'Cancel', icon: 'fa-solid fa-xmark' },
  ],
  rejectClose: false,
  render: dressUp,
});
if (!answer || typeof answer !== 'object') return;

const { shape, size, lineWidth, magical, color, touched } = answer;

const px = canvas.dimensions.distancePixels;
const shapes = [];
if (shape === 'burst') {
  shapes.push({ type: 'circle', gridBased: true, x: 0, y: 0, radius: size * px });
} else if (shape === 'cube') {
  shapes.push({ type: 'rectangle', gridBased: true, x: 0, y: 0, width: size * px, height: size * px });
} else {
  shapes.push({ type: 'rectangle', gridBased: true, x: 0, y: 0, width: size * px, height: lineWidth * px });
}

const statusId = magical ? 'dsctConcMagic' : 'dsctConcMundane';
const label = magical ? 'Magical Concealment' : 'Concealment';

const regionData = {
  name: `${label} Area`,
  shapes,
  color: (touched && color) ? color : (magical ? '#7a4fd0' : '#9aa0a6'),
  visibility: CONST.REGION_VISIBILITY.ALWAYS,
  highlightMode: 'coverage',
  behaviors: [{
    type: `${M}.statusEffect`,
    name: label,
    system: { statusId, dispositions: [], overlay: false },
  }],
};

const region = await canvas.regions.placeRegion(regionData, {});
if (!region) return;

ui.notifications.info(`${label} area placed. Reshape it with the region tools, or edit it on its sheet.`);
